<template>
  <div><el-button v-hasPermi="['paicli:session:read']" :disabled="!sessionId" @click="start">分页查看完整会话与工具记录</el-button><el-drawer v-model="open" title="完整会话记录与固定读取范围" size="900px"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-select v-model="kind" :disabled="busy" @change="changeKind"><el-option label="会话消息" value="messages" /><el-option label="中心工具执行事实" value="toolCalls" /><el-option label="批准与裁决记录" value="approvals" /><el-option label="完整产物元数据" value="artifacts" /></el-select><template v-if="kind==='messages'"><p class="pc-muted">固定末尾序号 {{ messages?.endSequence ?? '待读取' }} · 当前游标 {{ messages?.cursor ?? 0 }}</p><ConversationPane :messages="messages?.messages || []" :session-id="sessionId" :events="[]" :loading="busy" /></template><template v-else><p class="pc-muted">固定末尾 ID {{ records?.endId ?? '待读取' }} · 当前游标 {{ records?.cursor ?? '0' }}</p><article v-for="entry in records?.entries" :key="String(entry.id)"><pre class="pc-pre">{{safeText(entry)}}</pre><ArtifactEvidence :result="entry.result" :session-id="sessionId" :text-available="kind !== 'artifacts' || entry.kind === 'TOOL_OUTPUT'" :artifact-id="kind==='artifacts'?String(entry.id):typeof entry.artifactId==='string'?entry.artifactId:undefined" /></article><el-empty v-if="records && !records.entries.length" description="当前范围没有记录" /></template><div class="pc-actions"><el-button :loading="busy" :disabled="position===0" @click="previous">上一批记录</el-button><el-button :loading="busy" :disabled="!hasMore" @click="next">下一批记录</el-button><el-button :loading="busy" @click="changeKind">从当前末尾重新读取</el-button></div><p class="pc-muted">每批最多 200 条并受中心字节上限控制；翻页保留首次末尾范围。批准凭据与原始系统提示仍由服务端独立权限控制。</p></el-drawer></div>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {checkPermi} from '@/utils/permission'
import {getSessionMessages,getSessionRecords} from '@/api/paicli/sessions'
import type {PcMessagePage,PcRecordPage} from '@/types/paicli'
import ConversationPane from './ConversationPane.vue'
import ArtifactEvidence from './ArtifactEvidence.vue'
import {safeText} from '../model'
import {useOperations} from '../useOperations'
const props=defineProps<{sessionId:string;initialKind?:'messages'|'toolCalls'|'approvals'|'artifacts'}>(),{busy,error,run}=useOperations(),open=ref(false),kind=ref<'messages'|'toolCalls'|'approvals'|'artifacts'>(props.initialKind ?? 'messages'),messages=ref<PcMessagePage>(),records=ref<PcRecordPage>(),position=ref(0),hasMore=computed(()=>kind.value==='messages'?messages.value?.hasMore:records.value?.hasMore)
let generation=0,offsets=['0'],controller:AbortController|undefined
async function load(after:string,end?:number|string){if(!props.sessionId||!checkPermi(['paicli:session:read']))return false;controller?.abort();controller=new AbortController();const id=props.sessionId,selected=kind.value,g=++generation;let ok=false;await run(async()=>{if(selected==='messages'){const response=await getSessionMessages(id,Number(after),typeof end==='number'?end:undefined,controller!.signal);if(g===generation&&id===props.sessionId){messages.value=response.data;ok=true}}else{const response=await getSessionRecords(id,selected,after,typeof end==='string'?end:undefined,controller!.signal);if(g===generation&&id===props.sessionId){records.value=response.data;ok=true}}});return ok}
async function start(){if(busy.value||!props.sessionId||!checkPermi(['paicli:session:read']))return;open.value=true;await changeKind()}
async function changeKind(){messages.value=undefined;records.value=undefined;position.value=0;offsets=['0'];await load('0')}
async function next(){if(!hasMore.value||busy.value)return;const current=kind.value==='messages'?messages.value:records.value;if(!current)return;const after=String(current.cursor),end='endSequence' in current?current.endSequence:current.endId;if(await load(after,end)){offsets[position.value+1]=after;position.value++}}
async function previous(){if(position.value===0||busy.value)return;const current=kind.value==='messages'?messages.value:records.value;if(!current)return;const end='endSequence' in current?current.endSequence:current.endId;if(await load(offsets[position.value-1]!,end))position.value--}
watch(()=>props.sessionId,()=>{generation++;controller?.abort();open.value=false;messages.value=undefined;records.value=undefined});onBeforeUnmount(()=>{generation++;controller?.abort()})
</script>
